LOGO_RED = "#e0242b"          # 2.98.9 (wish of Daniel): the person in the logo is a red silhouette and walks to and fro


def _wm_walk(svg):
    """2.98.9, logo variant C «Kamera folgt»: the red person walks to and fro inside the field of view (steps), the corner
    marks go with it and the field of view swings along - like the head following a person. CSS only (no script)."""
    m = re.search(r'<path d="M([\d.]+) ([\d.]+) L[^"]*" fill="url\(#mwf[^)]*\)"/>', svg)
    f = re.search(r'<g transform="translate\(([\d.]+) ([\d.]+)\) scale\(([\d.]+)\)" fill="#e8590c"[^>]*>.*?</g>', svg)
    b = re.search(r'<g fill="none" stroke="currentColor" stroke-width="[\d.]+" stroke-linecap="round" stroke-linejoin="round"><path d="[^"]*"/></g>', svg)
    if not (m and f and b):
        return svg
    tx, ty, sc = (float(v) for v in f.groups())
    ex, ey = float(m.group(1)), float(m.group(2))
    amp = round(22.0 * sc / 1.6 if sc < 1.3 else 22.0, 1)
    ang = round(math.degrees(math.atan2(amp, max(1.0, ey - ty))), 1)
    R = LOGO_RED
    person = ('<g transform="translate(%.1f %.1f) scale(%.2f)" fill="%s" stroke="%s" stroke-linecap="round" stroke-linejoin="round">'
              '<circle cx="1" cy="-15.5" r="5.2" stroke="none"/><path d="M0.5 -9 L-0.5 3" stroke-width="8"/>'
              '<g class="wl1"><path d="M-0.5 3 L-5 13.5" stroke-width="4.6" fill="none"/></g><g class="wl2"><path d="M-0.5 3 L4.5 13" stroke-width="4.6" fill="none"/></g>'
              '<g class="wa1"><path d="M0.5 -6 L-5.5 0.5" stroke-width="3.6" fill="none"/></g><g class="wa2"><path d="M0.5 -6 L6 -0.5" stroke-width="3.6" fill="none"/></g></g>') % (tx, ty, sc, R, R)
    cone = m.group(0).replace("<path ", '<path class="wmc" style="transform-origin:%.1fpx %.1fpx;--wa:%.1fdeg" ' % (ex, ey, ang), 1)
    out = svg.replace(m.group(0), cone, 1)
    out = out.replace(f.group(0) + b.group(0), '<g class="wmw" style="--wx:%.1fpx">' % amp + person + b.group(0) + "</g>", 1)
    return out


WORDMARK_W6 = _wm_walk(WORDMARK_W6)
WORDMARK_W1 = _wm_walk(WORDMARK_W1)
WORDMARK_CSS = ("header h1.wm .wmc,header h1.wm .wmw{transform-box:view-box}header h1.wm .wmw{animation:wmw 7s ease-in-out infinite}"
                "header h1.wm .wmc{animation:wmc 7s ease-in-out infinite}"
                "header h1.wm .wl1,header h1.wm .wl2,header h1.wm .wa1,header h1.wm .wa2{transform-box:fill-box;transform-origin:50% 0}"
                "header h1.wm .wa1,header h1.wm .wa2{transform-origin:100% 0}"
                "header h1.wm .wl1,header h1.wm .wa2{animation:wms .7s ease-in-out infinite}header h1.wm .wl2,header h1.wm .wa1{animation:wms .7s ease-in-out infinite reverse}"
                "@keyframes wmw{0%,100%{transform:translateX(calc(-1*var(--wx)))}50%{transform:translateX(var(--wx))}}"
                "@keyframes wmc{0%,100%{transform:rotate(calc(-1*var(--wa)))}50%{transform:rotate(var(--wa))}}"
                "@keyframes wms{0%,100%{transform:rotate(18deg)}50%{transform:rotate(-18deg)}}"
                "@media (prefers-reduced-motion:reduce){header h1.wm .wmw,header h1.wm .wmc,header h1.wm .wl1,header h1.wm .wl2,header h1.wm .wa1,header h1.wm .wa2{animation:none}}"
                "header h1.wm{gap:8px}header h1.wm::before{display:none}header h1.wm svg{overflow:visible}"
                "header h1.wm svg{display:block;color:var(--txt,#e8eef5)}header h1.wm .wm6{height:46px;width:auto}"
                "header h1.wm .wm1{height:76px;width:auto;display:none}"
                "@media (max-width:560px){header h1.wm .wm6{display:none}header h1.wm .wm1{display:block}}")


def wordmark_h1(m):
    """the substitution for <h1 ...>MoveEye</h1> (render_page)"""
    tag = m.group(1)
    tag = tag[:-1] + (' class="wm"' if "class=" not in tag else "") + ">"
    return tag + WORDMARK_W6 + WORDMARK_W1
